package com.sirithree.shopops.admin.benchmark.v1.dataset.stage5;
import static org.assertj.core.api.Assertions.assertThat; import java.util.List; import java.util.Map; import org.junit.jupiter.api.Test;
class IdempotencyNearDuplicateReviewTest { @Test void everyStructuredCandidateHasCriticDecision() throws Exception { Map<String,Object> doc=Stage5IdempotencyDatasetSupport.resource("/benchmark/v1/idempotency/stage5/idempotency-near-duplicate-review.json"); @SuppressWarnings("unchecked") List<Map<String,Object>> decisions=(List<Map<String,Object>>)doc.get("decisions"); assertThat(decisions).hasSize(((Number)doc.get("candidateCount")).intValue()); assertThat(((Number)doc.get("unresolvedCount")).intValue()).isZero(); assertThat(decisions).allSatisfy(d->assertThat(String.valueOf(d.get("reviewDecision"))).isIn("SAME_ROOT","KEEP_DISTINCT")); }}
